INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(32311, 'John 11:14', 'John', 11, 14, 'نو عیسی هغوی ته ښکاره وویل: «ایلعازر مړ شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_14.mp3', '', 1761754199, 1761754199),
(32312, 'John 11:15', 'John', 11, 15, 'خو زه ستاسو په خاطر خوشحاله یم چې هلته نه وم، ځکه چې تاسو به اوس په رښتیا ایمان راوړئ. راځئ چې هغه ته ورشو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_15.mp3', '', 1761754199, 1761754199),
(32313, 'John 11:16', 'John', 11, 16, 'توما چې د غبرګوني په نوم هم یادېده، نورو شاګردانو ته وویل: «راځئ چې مونږ هم لاړ شو او د هغه سره مړه شو.» عیسی قیامت او ژوندون دی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_16.mp3', '', 1761754199, 1761754199),
(32314, 'John 11:17', 'John', 11, 17, 'کله چې عیسی هغه ځای ته ورسېده، څلور ورځې کېدلې چې د ایلعازر مړی په قبر کې ایښودل شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_17.mp3', '', 1761754199, 1761754199),
(32315, 'John 11:18', 'John', 11, 18, 'بیت‌عنیا د اورشلیم نه شاوخوا درې کیلومتره لېرې ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_18.mp3', '', 1761754199, 1761754199),
(32316, 'John 11:19', 'John', 11, 19, 'او د اورشلیم نه د یهودیې ډېر خلک مرتا او مریم ته راغلي وو چې د هغوی د ورور د مړینې په خاطر ورته تسلي ورکړي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_19.mp3', '', 1761754199, 1761754199),
(32317, 'John 11:20', 'John', 11, 20, 'نو کله چې مرتا د عیسی د راتللو څخه خبره شوه، د هغه مخې ته ورغله، خو مریم په کور کې پاتې شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_20.mp3', '', 1761754199, 1761754199),
(32318, 'John 11:21', 'John', 11, 21, 'مرتا عیسی ته وویل: «استاذه، که ته دلته وای، نو زما ورور به نه وای مړ شوی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_21.mp3', '', 1761754199, 1761754199),
(32319, 'John 11:22', 'John', 11, 22, 'خو زه اوس هم په دې پوهېږم چې که ته د خدای څخه هرڅه وغواړې، نو خدای به یې درکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_22.mp3', '', 1761754199, 1761754199),
(32320, 'John 11:23', 'John', 11, 23, 'عیسی هغې ته وویل: «ستا ورور به بېرته راژوندی شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_23.mp3', '', 1761754199, 1761754199),
(32321, 'John 11:24', 'John', 11, 24, 'مرتا وویل: «زه پوهېږم چې هغه به د قیامت په ورځ راژوندی شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_24.mp3', '', 1761754199, 1761754199),
(32322, 'John 11:25', 'John', 11, 25, 'عیسی هغې ته وویل: «زه قیامت او ژوندون یم. که څوک په ما باندې ایمان راوړي که هغه مړ هم شي، خو بیا به هم ژوندی وي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_25.mp3', '', 1761754199, 1761754199),
(32323, 'John 11:26', 'John', 11, 26, 'او که څوک ژوندی وي او په ما باندې ایمان راوړي، نو هغه به هېڅکله هم مړ نه شي. ایا په دې باندې باور کوې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_26.mp3', '', 1761754199, 1761754199),
(32324, 'John 11:27', 'John', 11, 27, 'هغې وویل: «هو، استاذه! زه په دې ایمان لرم چې ته مسیح یعنې د خدای زوی یې، د چا په هکله چې خدای ویلي دي چې هغه باید نړۍ ته راشي.» عیسی ژاړي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_27.mp3', '', 1761754199, 1761754199),
(32325, 'John 11:28', 'John', 11, 28, 'کله چې مرتا دا خبره وکړه، نو لاړه او خپلې خور ته یې غږ وکړ او په پټه یې ورته وویل: «استاذ راغلی دی او تا غواړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_28.mp3', '', 1761754199, 1761754199),
(32326, 'John 11:29', 'John', 11, 29, 'کله چې مریم دا واورېدل، نو زر راپاڅېدله او عیسی ته ورغله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_29.mp3', '', 1761754199, 1761754199),
(32327, 'John 11:30', 'John', 11, 30, 'عیسی لا کلي ته رسېدلی نه ؤ او لا په هماغه ځای کې ؤ چې مرتا یې لیدلو ته ورغلې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_30.mp3', '', 1761754199, 1761754199),
(32328, 'John 11:31', 'John', 11, 31, 'کوم خلک چې مریم ته د تسلۍ ورکولو دپاره راغلي وو او د هغې په کور کې وو، نو کله یې چې ولیدل چې هغه په بیړه له کوره وځي نو هغې پسې روان شول. هغوی فکر کاوه چې هغه قبر ته روانه ده چې هلته وژاړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_31.mp3', '', 1761754199, 1761754199),
(32329, 'John 11:32', 'John', 11, 32, 'مریم هغه ځای ته ورسېدله چې عیسی په کې ؤ او څنګه یې چې هغه ولیده، نو پښو ته یې پرېوتله او ویې ویل: «استاذه، که ته دلته وای، نو زما ورور به نه وای مړ شوی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_32.mp3', '', 1761754199, 1761754199),
(32330, 'John 11:33', 'John', 11, 33, 'کله چې عیسی هغه ولیدله چې ژاړي او همدارنګه کوم خلک چې د هغې سره راغلي وو هم ژاړي، نو سوړ اوسېلی یې وویست او ډېر خفه شو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_33.mp3', '', 1761754199, 1761754199),
(32331, 'John 11:34', 'John', 11, 34, 'او د هغوی نه یې پوښتنه وکړه: «د هغه قبر چېرته دی؟» هغوی ځواب ورکړ: «ښاغلیه، راشه او ویې ګوره.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_34.mp3', '', 1761754199, 1761754199),
(32332, 'John 11:35', 'John', 11, 35, 'عیسی په ژړا شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_35.mp3', '', 1761754199, 1761754199),
(32333, 'John 11:36', 'John', 11, 36, 'بیا خلکو وویل: «وګورئ هغه ورباندې څومره ګران ؤ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_36.mp3', '', 1761754199, 1761754199),
(32334, 'John 11:37', 'John', 11, 37, 'خو ځینو یې وویل: «دې سړي چې د هغه ړوند سړي سترګې بینا کړلې، ایا دا یې نه شو کولای چې ایلعازر یې د مرګ نه ژغورلی وای؟» ایلعازر راژوندی کیږي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_37.mp3', '', 1761754199, 1761754199),
(32335, 'John 11:38', 'John', 11, 38, 'عیسی یوځل بیا سوړ اوسېلی وویست او قبر ته ورغی. دا قبر یو غار ؤ چې خولې ته یې یوه تیږه ایښودل شوې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_38.mp3', '', 1761754199, 1761754199),
(32336, 'John 11:39', 'John', 11, 39, 'عیسی خلکو ته امر وکړ: «تیږه لېرې کړئ.» مرتا د مړ شوي سړي خور هغه ته وویل: «استاذه، اوس خو د هغه د مرګ څلور ورځې شوې دي او بوی به یې کړی وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_39.mp3', '', 1761754199, 1761754199),
(32337, 'John 11:40', 'John', 11, 40, 'عیسی هغې ته وویل: «ایا تاته مې نه وو ویلي چې که چېرې ته ایمان ولرې، نو د خدای جلال به ووینې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_40.mp3', '', 1761754199, 1761754199),
(32338, 'John 11:41', 'John', 11, 41, 'نو خلکو تیږه لېرې کړه. بیا عیسی پورته اسمان ته وکتل او ویې ویل: «ای پلاره، زه ستا شکر کوم چې زما دعا دې واورېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_41.mp3', '', 1761754199, 1761754199),
(32339, 'John 11:42', 'John', 11, 42, 'زه پوهېدم چې ته تل زما دعا اورې، خو ما دا د دې خلکو په خاطر چې دلته ولاړ دي وویل، ترڅو هغوی په دې باندې ایمان راوړي چې زه تا رالېږلی یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_42.mp3', '', 1761754199, 1761754199),
(32340, 'John 11:43', 'John', 11, 43, 'کله چې عیسی دعا خلاصه کړه، نو په لوړ اواز یې چیغه کړه: «ای ایلعازره، راووځه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_43.mp3', '', 1761754199, 1761754199),
(32341, 'John 11:44', 'John', 11, 44, 'نو هغه مړی چې لاسونه او پښې یې په کفن کې تاو شوې وې او مخ یې په دستمال کې پټ ؤ، راووت. عیسی هغوی ته وویل: «هغه راخلاص کړئ او پرېږدئ چې لاړ شي.» د عیسی په خلاف دسیسه (متي ۲۶‏:‌۱‌‏-‌۵ او مرقوس ۱۴‏:‌۱‌‏-‌۲ او لوقا ۲۲‏:‌۱‌‏-‌۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_44.mp3', '', 1761754199, 1761754199),
(32342, 'John 11:45', 'John', 11, 45, 'نو ډېرو خلکو چې د مریم لیدلو ته راغلي وو، کله چې هغوی هغه څه چې عیسی وکړل ولیدل، نو په هغه باندې یې ایمان راوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_45.mp3', '', 1761754199, 1761754199),
(32343, 'John 11:46', 'John', 11, 46, 'خو د هغوی څخه ځینې یې فریسیانو ته ورغلل او کوم کارونه چې عیسی کړي وو هغوی ته یې وویل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_46.mp3', '', 1761754199, 1761754199),
(32344, 'John 11:47', 'John', 11, 47, 'بیا فریسیانو او مشرانو کاهنانو شورا راوغوښتله او ویې ویل: «څه باید وکړو؟ ځکه چې دا سړی ډېرې معجزې ښکاره کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_47.mp3', '', 1761754199, 1761754199),
(32345, 'John 11:48', 'John', 11, 48, 'که مونږ هغه پرېږدو چې همداسې کارونه وکړي نو ټول خلک به ورباندې ایمان راوړي، بیا به رومیان راشي او زمونږ د خدای کور او زمونږ ټول قوم به له منځه یوسي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_48.mp3', '', 1761754199, 1761754199),
(32346, 'John 11:49', 'John', 11, 49, 'خو په هغوی کې یو تن چې قیافا نومېده او په هغه کال لوی کاهن ؤ، وویل: «تاسو نه پوهېږئ!', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_49.mp3', '', 1761754199, 1761754199),
(32347, 'John 11:50', 'John', 11, 50, 'په دې نه پوهېږئ چې ستاسو دپاره دا ښه ده چې یو کس د ټول قوم په خاطر مړ شي، نه دا چې ټول قوم تباه شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_50.mp3', '', 1761754199, 1761754199),
(32348, 'John 11:51', 'John', 11, 51, 'هغه دا خبره له خپله ځانه ونه کړه بلکې د دې دپاره چې هغه په هغه کال لوی کاهن ؤ، نو هغه پېشګویي وکړه چې عیسی به د یهودو د قوم په خاطر مړ شي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_51.mp3', '', 1761754199, 1761754199),
(32349, 'John 11:52', 'John', 11, 52, 'او یوازې د هغه قوم دپاره نه بلکې د خدای ټول خواره واره اولادونه چې په مختلفو ځایونو کې اوسیږي سره یوځای کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_52.mp3', '', 1761754199, 1761754199),
(32350, 'John 11:53', 'John', 11, 53, 'نو د هماغې ورځې نه هغوی د عیسی د وژلو پرېکړه وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_53.mp3', '', 1761754199, 1761754199),
(32351, 'John 11:54', 'John', 11, 54, 'له هغې وروسته عیسی نور د خلکو په منځ کې ښکاره نه ګرځېده بلکې د هغه ځای نه یوې سیمې ته چې دښتې ته نژدې وه، یعنې د افرایم په نوم ښار ته لاړ او د خپلو شاګردانو سره هلته پاتې شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_54.mp3', '', 1761754199, 1761754199),
(32352, 'John 11:55', 'John', 11, 55, 'د یهودیانو د فسحې اختر نژدې ؤ او ډېر خلک د کلیوالي سیمو نه اورشلیم ته راغلل چې د اختر نه مخکې د پاکوالي مراسم سرته ورسوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_55.mp3', '', 1761754199, 1761754199),
(32353, 'John 11:56', 'John', 11, 56, 'هغوی عیسی لټاوه او څنګه چې هغوی د خدای په کور کې سره راټول شول نو یو بل ته یې وویل: «تاسو څه فکر کوئ، ایا هغه به د اختر جشن ته رانه شي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_56.mp3', '', 1761754199, 1761754199),
(32354, 'John 11:57', 'John', 11, 57, 'مشرانو کاهنانو او فریسیانو دا حکم کړی ؤ، که هرڅوک پوه شي چې عیسی چېرته دی، نو دوی ته دې خبر ورکړي چې هغه ونیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john11_verse_57.mp3', '', 1761754199, 1761754199),
(32355, 'Revelation 5:1', 'Revelation', 5, 1, 'بیا ما د هغه کس په ښي لاس کې چې په تخت باندې ناست ؤ، یو طومار ولیده چې دننه او دباندې دواړو خواوو باندې یې لیکنه شوې وه او اووه مهرونه ورباندې لګېدلي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_1.mp3', '', 1761754199, 1761754199),
(32356, 'Revelation 5:2', 'Revelation', 5, 2, 'ما یوه قوي فرښته ولیدله چې په لوړ اواز یې اعلان کاوه: «څوک د دې لایق دی چې طومار خلاص کړي او مهرونه یې مات کړي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_2.mp3', '', 1761754199, 1761754199),
(32357, 'Revelation 5:3', 'Revelation', 5, 3, 'خو نه په اسمان کې، نه په ځمکه او نه هم د ځمکې لاندې داسې څوک ؤ چې وکولای شي هغه طومار خلاص کړي او یا یې دننه وګوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_3.mp3', '', 1761754199, 1761754199),
(32358, 'Revelation 5:4', 'Revelation', 5, 4, 'ما سخت وژړل، ځکه چې هېڅوک هم د دې لایق نه ؤ چې هغه طومار خلاص کړي او دننه یې وګوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_4.mp3', '', 1761754199, 1761754199),
(32359, 'Revelation 5:5', 'Revelation', 5, 5, 'خو د مشرانو څخه یو یې راته وویل: «نور مه ژاړه، ځکه چې د یهودا د قبیلې هغه زمری چې د داود د نسل څخه دی، بریالی شوی دی چې طومار خلاص کړي او اووه مهرونه یې مات کړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_5.mp3', '', 1761754199, 1761754199),
(32360, 'Revelation 5:6', 'Revelation', 5, 6, 'بیا ما د تخت ترمنځ او څلورو اسماني موجوداتو او مشرانو په منځ کې ولیدل چې یو وری ولاړ دی او داسې معلومېده چې حلال شوی وي. هغه وري اووه ښکرونه او اووه سترګې لرلې چې هغه د خدای اووه روحونه وو چې ټولې نړۍ ته لېږل شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_6.mp3', '', 1761754199, 1761754199),
(32361, 'Revelation 5:7', 'Revelation', 5, 7, 'هغه وری راغی او په تخت باندې د ناست کس د ښي لاس نه یې هغه طومار واخیست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_7.mp3', '', 1761754199, 1761754199),
(32362, 'Revelation 5:8', 'Revelation', 5, 8, 'څنګه چې یې هغه طومار واخیست، نو هغه څلور اسماني موجودات او څلورویشت مشران د وري په مخکې په سجده شول. د هر مشر سره یو چنګ او د خوشبویۍ نه ډک د سرو زرو جامونه وو چې د خدای د خلکو دعاګانې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_8.mp3', '', 1761754199, 1761754199),
(32363, 'Revelation 5:9', 'Revelation', 5, 9, 'هغوی یوه نوې سندره ویله: ته لایق یې د دې چې طومار واخلې او مهرونه یې مات کړې ځکه چې ته یې حلال شوی او په خپله وینه دې د خدای دپاره په بیه واخیستل خلک د هرې قبیلې، هرې ژبې، هر قوم او هر ملت څخه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_9.mp3', '', 1761754199, 1761754199),
(32364, 'Revelation 5:10', 'Revelation', 5, 10, 'تا کړه جوړه د هغوی څخه شاهي کورنۍ او کاهنان د خدای او پاچاهي به کوي هغوی په ځمکه باندې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_10.mp3', '', 1761754199, 1761754199),
(32365, 'Revelation 5:11', 'Revelation', 5, 11, 'یوځل بیا مې وکتل او د زرګونو او میلیونونو فرښتو اوازونه مې واورېدل چې د تخت او اسماني مخلوقاتو او مشرانو نه ګردچاپېره ولاړې وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation5_verse_11.mp3', '', 1761754199, 1761754199),
