(32379, 'Hebrews 9:11', 'Hebrews', 9, 11, 'خو کله چې مسیح د لوی کاهن په توګه د هغو ښو شیانو دپاره چې پېښ شوي دي او لا تر‌اوسه موجود دي، راغی، نو هغه هغې لویې او کاملې خېمې ته چې د انسان په لاس نه ده جوړه شوې او د دې نړۍ سره تړاو نه لري، ننوت.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews9_verse_11.mp3', '', 1761754199, 1761754199),
(32380, 'Hebrews 9:12', 'Hebrews', 9, 12, 'هغه یوځل او د تل دپاره د وزو او خوسیانو د وینې سره هغه ډېر سپېڅلي ځای ته وردننه نه شو، بلکې د خپلې وینې سره هلته ننوت او مونږ ته یې د تل دپاره خلاصون تر‌لاسه کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews9_verse_12.mp3', '', 1761754199, 1761754199),
