(32398, 'Matthew 9:2', 'Matthew', 9, 2, 'په دې وخت کې څو کسانو یو شل سړی چې په کټ کې پروت ؤ هغه ته راوست. عیسی چې د هغوی ایمان ولیده، نو هغه شل سړي ته یې وویل: «زویه! ډاډه اوسه، ستا ګناهونه وبخښل شول.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_2.mp3', '', 1761754199, 1761754199),
(32399, 'Matthew 9:3', 'Matthew', 9, 3, 'په دې خبرې د شریعت ځینې عالمانو د خپلو ځانونو سره وویل: «دا سړی کفر وایي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_3.mp3', '', 1761754199, 1761754199),
(32400, 'Matthew 9:4', 'Matthew', 9, 4, 'خو عیسی پوهېده چې د هغوی په زړه کې څه دي او ورته ویې ویل: «ستاسو په زړونو کې ولې داسې بد فکرونه ګرځي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_4.mp3', '', 1761754199, 1761754199),
(32401, 'Matthew 9:5', 'Matthew', 9, 5, 'ایا دا خبره اسانه ده چې وویل شي ستا ګناهونه وبخښل شول او یا وویل شي چې پاڅېږه او وګرځه؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_5.mp3', '', 1761754199, 1761754199),
(32402, 'Matthew 9:6', 'Matthew', 9, 6, 'خو زه به تاسو ته ثابته کړم چې د انسان زوی د ځمکې په مخ دا واک او اختیار لري چې ګناهونه وبخښي.» نو هغه شل سړي ته یې وویل: «پاڅېږه، کټ دې واخله او خپل کور ته لاړ شه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_6.mp3', '', 1761754199, 1761754199),
(32403, 'Matthew 9:7', 'Matthew', 9, 7, 'هغه پاڅېد او کور ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_7.mp3', '', 1761754199, 1761754199),
(32404, 'Matthew 9:8', 'Matthew', 9, 8, 'کله چې خلکو دا پېښه ولیدله نو ووېرېدل او د خدای ثنا یې وویله چې انسان ته یې داسې واک او اختیار ورکړی دی. عیسی متي ته بلنه ورکوي (مرقوس ۲‏:‌۱۳‌‏-‌۱۷ او لوقا ۵‏:‌۲۷‌‏-‌۳۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_8.mp3', '', 1761754199, 1761754199),
(32405, 'Matthew 9:9', 'Matthew', 9, 9, 'کله چې عیسی له هغه ځای څخه تېرېده، نو په لاره کې یې د متي په نوم یو سړی ولیده چې د مالیې راټولولو په ځای کې ناست ؤ. عیسی هغه ته وویل: «ما پسې راځه.» متي راپاڅېد او په هغه پسې روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_9.mp3', '', 1761754199, 1761754199),
(32406, 'Matthew 9:10', 'Matthew', 9, 10, 'بیا عیسی د متي په کور کې ډوډۍ ته ناست ؤ چې ډېر مالیه ټولوونکي او نور ګناهکاران راغلل او د عیسی او د هغه د شاګردانو سره دسترخوان ته کښېناستل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_10.mp3', '', 1761754199, 1761754199),
(32407, 'Matthew 9:11', 'Matthew', 9, 11, 'کله چې فریسیانو دا ولیدل، نو د عیسی د شاګردانو نه یې پوښتنه وکړه: «ستاسو استاذ ولې د مالیه ټولوونکو او نورو ګناهکارانو سره یوځای ډوډۍ خوري؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_11.mp3', '', 1761754199, 1761754199),
(32408, 'Matthew 9:12', 'Matthew', 9, 12, 'عیسی د هغوی خبرې واورېدلې او ویې ویل: «روغ خلک ډاکتر ته اړتیا نه لري بلکې ناروغان یې لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_12.mp3', '', 1761754199, 1761754199),
(32409, 'Matthew 9:13', 'Matthew', 9, 13, 'لاړ شئ او د خدای د کلام د دې لیکنو په معنی باندې ځانونه پوه کړئ: ‹زه ستاسو څخه غواړم چې په نورو رحم وکړئ، نه د قربانۍ وړاندې کول.› ځکه چې زه د دې دپاره نه یم راغلی چې پرهېزګاران راوبولم بلکې ګناهکاران راوبولم.» د روژې په هکله پوښتنه (مرقوس ۲‏:‌۱۸‌‏-‌۲۲ او لوقا ۵‏:‌۳۳‌‏-‌۳۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_13.mp3', '', 1761754199, 1761754199),
(32410, 'Matthew 9:14', 'Matthew', 9, 14, 'بیا د یحیی شاګردان عیسی ته راغلل او ورته ویې ویل: «ولې مونږ او فریسیان روژه نیسو او ستا شاګردان یې نه نیسي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew9_verse_14.mp3', '', 1761754199, 1761754199);